/**
 * Parity tests: the TypeScript pipeline against reference outputs generated
 * by the Python implementation (OpenCV 5.0.0 + MediaPipe 1.0.1, the versions
 * in model/pyproject.toml).
 *
 * The reference data lives in fixtures/ and was generated by scripts run
 * against model/src/data (see ui/README.md).
 */

import { expect, test } from 'vitest'
import faceUrl from './fixtures/face.jpg'
import faceCropUrl from './fixtures/face_crop.bin?url'
import leftCropUrl from './fixtures/left_crop.bin?url'
import rightCropUrl from './fixtures/right_crop.bin?url'
import probesRaw from './fixtures/cv2_probes.json'
import refRaw from './fixtures/ref.json'
import {
  getRectSubPix,
  projectPoints,
  rodrigues,
  rodriguesToVector,
  solvePnP,
  warpPerspective,
} from './cv'
import { getLandmarker, headPoseEst, landmarkDetection, normalizeFace } from './utils'
import type { CameraIntrinsics, ImageArray } from './utils'

const MPII_INTRINSICS: CameraIntrinsics = {
  focalLengthPx: 996.4509,
  principalPoint: { x: 624.6634, y: 364.0874 },
}

async function loadFaceImage(): Promise<ImageArray> {
  const blob = await (await fetch(faceUrl)).blob()
  const bitmap = await createImageBitmap(blob)
  const canvas = new OffscreenCanvas(bitmap.width, bitmap.height)
  const ctx = canvas.getContext('2d') as OffscreenCanvasRenderingContext2D
  ctx.drawImage(bitmap, 0, 0)
  const rgba = ctx.getImageData(0, 0, bitmap.width, bitmap.height).data
  const rgb = new Uint8Array(bitmap.width * bitmap.height * 3)
  for (let i = 0, j = 0; i < rgb.length; i += 3, j += 4) {
    rgb[i] = rgba[j]
    rgb[i + 1] = rgba[j + 1]
    rgb[i + 2] = rgba[j + 2]
  }
  return { data: rgb, rows: bitmap.height, cols: bitmap.width }
}

test('warpPerspective matches cv2 within 1 LSB (random H, borders included)', async () => {
  const [rows, cols] = probes.warp.src_shape
  const src = { data: new Uint8Array(flatten(probes.warp.src)), rows, cols }
  const [dw, dh] = probes.warp.dsize
  for (const tc of probes.warp.cases) {
    const out = await warpPerspective(src, flatten(tc.H), { width: dw, height: dh })
    const expected = flatten(tc.dst)
    let maxDiff = 0
    for (let k = 0; k < expected.length; k++) {
      maxDiff = Math.max(maxDiff, Math.abs(out.data[k] - expected[k]))
    }
    // The WASM backend has no FMA instruction, so last-ulp rounding can
    // shift an occasional pixel by 1 vs the native x86 wheel (measured: at
    // most 1 pixel in one case). Everything else is byte-exact.
    expect(maxDiff).toBeLessThanOrEqual(1)
  }
})

test('getRectSubPix matches cv2 byte for byte (all border paths)', async () => {
  const [rows, cols] = probes.subpix.src_shape
  const src = { data: new Uint8Array(flatten(probes.subpix.src)), rows, cols }
  for (const tc of probes.subpix.cases) {
    const patch = await getRectSubPix(
      src,
      { width: probes.subpix.win[0], height: probes.subpix.win[1] },
      { x: tc.center[0], y: tc.center[1] },
    )
    expect(patch.data).toEqual(new Uint8Array(flatten(tc.patch)))
  }
})

test('Rodrigues matches cv2 in both directions', async () => {
  for (const tc of probes.rodrigues) {
    const R = await rodrigues(tc.v)
    expectAllClose(R, flatten(tc.R), 1e-12)
    const v2 = await rodriguesToVector(R)
    expectAllClose(v2, tc.v2, 1e-12)
    if (tc.R3 !== null) {
      const R3 = await rodrigues(v2)
      expectAllClose(R3, flatten(tc.R3), 1e-12)
    }
  }
})

test('projectPoints matches cv2 exactly', async () => {
  const p = probes.misc.projectPoints_probe
  const pts = await projectPoints(
    GENERIC_MODEL,
    new Float64Array(p.rvec),
    new Float64Array(p.t),
    new Float64Array([p.K[0], 0, p.K[1], 0, p.K[0], p.K[2], 0, 0, 1]),
  )
  // exact on x86-64; the slack only absorbs cross-platform differences
  expectAllClose(pts, flatten(p.pts), 1e-12)
})

test('solvePnP SQPNP matches cv2 (synthetic poses)', async () => {
  for (const tc of probes.pnp) {
    const [f, cx, cy] = tc.K
    const imagePoints = new Float64Array(16)
    const ids = [33, 133, 362, 263, 61, 291, 1, 152]
    ids.forEach((id, i) => {
      imagePoints[2 * i] = tc.landmarks[id][0]
      imagePoints[2 * i + 1] = tc.landmarks[id][1]
    })
    const { rvec, tvec } = await solvePnP(
      GENERIC_MODEL,
      imagePoints,
      new Float64Array([f, 0, cx, 0, f, cy, 0, 0, 1]),
    )
    // bit-identical to the recorded cv2 output on x86-64; the 1e-9 slack
    // absorbs cross-platform differences 
    expectAllClose(rvec, tc.rvec_est, 1e-9)
    expectAllClose(tvec, tc.tvec_est, 1e-9)

    const R = await rodrigues(rvec)
    expectAllClose(R, flatten(tc.R_true), 1e-6)
    expectAllClose(tvec, tc.tvec_true, 1e-6)
  }
})

test('head pose matches the Python pipeline to machine precision', async () => {
  const landmarks = ref.landmarks.map(([x, y]) => ({ x, y }))
  const intrinsics = MPII_INTRINSICS
  const [R, t] = await headPoseEst(landmarks, intrinsics)
  expectAllClose(R, flatten(ref.R), 1e-12)
  expectAllClose(t, flatten(ref.t), 1e-9)
})

test('normalization reproduces the Python crops byte for byte', async () => {
  const image = await loadFaceImage()
  const landmarks = ref.landmarks.map(([x, y]) => ({ x, y }))
  const intrinsics = MPII_INTRINSICS
  const [R, t] = await headPoseEst(landmarks, intrinsics)

  const { face, leftEye, rightEye, RVirtual } = await normalizeFace(image, landmarks, R, t, intrinsics)

  expectAllClose(RVirtual, flatten(ref.R_virtual), 1e-13)
  // The WASM backend lacks FMA, so an occasional pixel can differ from the
  // native x86 wheel by 1; assert that bound everywhere.
  const assertClose = async (name: string, got: Uint8Array, url: string) => {
    const expected = new Uint8Array(await (await fetch(url)).arrayBuffer())
    let maxDiff = 0
    for (let i = 0; i < expected.length; i++) {
      maxDiff = Math.max(maxDiff, Math.abs(got[i] - expected[i]))
    }
    expect(maxDiff, name).toBeLessThanOrEqual(1)
  }
  await assertClose('face', face.data, faceCropUrl)
  await assertClose('leftEye', leftEye.data, leftCropUrl)
  await assertClose('rightEye', rightEye.data, rightCropUrl)
})

test('browser FaceLandmarker agrees with Python to a few thousandths of a pixel', async () => {
  const image = await loadFaceImage()
  const model = await getLandmarker()
  const landmarks = landmarkDetection(model, image)

  expect(landmarks).not.toBeNull()
  let maxDiff = 0
  for (let i = 0; i < 478; i++) {
    maxDiff = Math.max(
      maxDiff,
      Math.abs(landmarks![i].x - ref.landmarks[i][0]),
      Math.abs(landmarks![i].y - ref.landmarks[i][1]),
    )
  }
  // Python (mediapipe 1.0.1) and the browser (tasks-vision wasm) run the same
  // model graph; residual differences are cross-runtime floating point.
  expect(maxDiff).toBeLessThan(0.01)
})

const probes = probesRaw as typeof probesRaw
const ref = refRaw as typeof refRaw

const GENERIC_MODEL = new Float64Array([
  -4.446, -2.664, -3.173, -1.856, -2.585, -3.758, 1.856, -2.585, -3.758,
  4.446, -2.664, -3.173, -2.456, 4.343, -4.284, 2.456, 4.343, -4.284,
  0.0, 1.127, -7.476, 0.0, 9.403, -4.264,
])

function expectAllClose(actual: ArrayLike<number>, expected: ArrayLike<number>, atol: number) {
  expect(actual.length).toBe(expected.length)
  for (let i = 0; i < actual.length; i++) {
    expect(Math.abs(actual[i] - expected[i])).toBeLessThanOrEqual(atol)
  }
}

/** Recursively flatten a nested JSON array of numbers. */
function flatten(value: unknown): number[] {
  if (typeof value === 'number') return [value]
  if (Array.isArray(value)) return value.flatMap(flatten)
  throw new Error('not a numeric array')
}
